/* RecipeBox layout. Where the box sits (float parameter) is set inline by Template:RecipeBox,
   this page only adds a minimum width and the phone layout. */
.aa-recipebox {
  display: flow-root;
  box-sizing: border-box;
  max-width: 100%;
  min-width: 320px; /* never squeezed narrower than this, also inside a row of boxes */
  min-width: min(320px, calc(100vw - 2rem)); /* on very small screens: the screen width */
  flex: 0 0 auto;   /* a flex row (like display:flex; flex-wrap:wrap) wraps the box instead of shrinking it */
}
.aa-recipebox table.wikitable {
  margin: 0;
  max-width: 100%;
  min-width: 100%;
}

/* Phones: a floated box gets its own line instead of squeezing the text */
@media (max-width: 500px) {
  .aa-recipebox-float {
    float: none !important;
    clear: both !important;
    margin: 0.5em 0 !important;
  }
}

/* The recipe card (same look as the item, skill and buff cards) */
.aa-rb {
  width: 320px;
  padding: 12px 14px;
  background: linear-gradient(to bottom, rgba(24, 28, 38, 0.97), rgba(10, 12, 18, 0.97));
  border: 1px solid #5a5040;
  border-radius: 3px;
  box-shadow: 0 0 0 1px #000, 0 4px 12px rgba(0, 0, 0, 0.6);
  color: #e8e4d8;
  font-size: 13px;
  line-height: 1.5;
  text-align: left;
}
.aa-rb-head {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  justify-content: space-between;
}
/* the product: icon + title (hover = the card of the item) */
.aa-rb-prod {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  min-width: 0;
}
.aa-rb-icon {
  flex: none;
  line-height: 0;
}
.aa-rb-title {
  display: flex;
  flex-direction: column;
  line-height: 1.25;
}
.aa-rb-kind,
.aa-rb-grade {
  color: #8a8478;
  font-size: 12px;
}
.aa-rb-name {
  font-size: 17px;
  font-weight: bold;
}
/* chance for 2x: a small tag at the right of the header */
.aa-rb-chip {
  flex: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 1px 8px;
  border: 1px solid #6a5d48;
  border-radius: 3px;
  background: rgba(240, 208, 96, 0.08);
  color: #f0d060;
  font-weight: bold;
  line-height: 1.3;
}
.aa-rb-chiplabel {
  color: #8a8478;
  font-size: 11px;
  font-weight: normal;
}
.aa-rb-sep {
  height: 1px;
  margin: 10px 0;
  background: linear-gradient(to right, transparent, #6a5d48, transparent);
}
.aa-rb-stats {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-left: 40px;   /* lines the facts up with the item names below (4px row padding + 32px icon + 4px gap): change here */
}
.aa-rb-statrow {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 28px;   /* each fact is only as wide as its text */
}
.aa-rb-label {
  color: #8a8478;
  font-size: 11px;
}
.aa-rb-mats {
  margin-bottom: 4px;
  font-size: 12px;
}
.aa-rb-labor {
  color: #F8D870;   /* the light gold of the labor text in the game */
  font-weight: bold;
}
.aa-rb-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.aa-rb-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 2px 4px;
  border-radius: 2px;
}
.aa-rb-row:hover {
  background: rgba(255, 255, 255, 0.05);
}
/* icon and name side by side: a long name that wraps keeps its indent to the right of the icon */
.aa-rb-item {
  flex-grow: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 4px;
}
.aa-rb-item .aa-itemtip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
}
.aa-rb-item .aa-itemtip > span:first-child {
  flex: none;   /* the icon never shrinks */
}
.aa-rb-coinlabel {
  color: #c9c3b4;
}
.aa-rb-amount {
  flex: none;
  color: #c9c3b4;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.aa-rb-foot {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}
.aa-rb-costlabel,
.aa-rb-note {
  display: block;
}
/* the Recipe Cost link keeps the normal text colour and shows no external-link icon; it underlines on hover */
.aa-rb-costlabel a,
.aa-rb-costlabel a:visited {
  color: inherit;
  text-decoration: none;
}
.aa-rb-costlabel a.external {
  background: none;
  padding-right: 0;
}
.aa-rb-costlabel a:hover {
  color: inherit;
  text-decoration: underline;
}
.aa-rb-note {
  color: #8a8478;
  font-size: 11px;
}
.aa-rb-cost {
  font-weight: bold;
  white-space: nowrap;
}
/* The hover cards open from the MIDDLE of the box towards the right (never closer to the left than the middle), level
   with the row / product that is hovered. They reach a little past the right edge of the box, which leaves the left half
   of the box free to move around in. The box is the reference for the position, so the row and the product must not be. */
.aa-rb {
  position: relative;
}
.aa-rb .aa-itemtip,
.aa-rb .aa-rb-item .aa-itemtip,
.aa-rb .aa-rb-row {
  position: static;
}
.aa-rb .aa-itemtip-card,
.aa-rb .aa-itemtip-left .aa-itemtip-card {
  top: auto;
  margin-top: -8px;
  left: 50%;
  right: auto;
  width: 250px;
  max-width: none;
  padding: 0;
}
/* the hover cards of the items: in the card they must not be clipped */
.aa-rb .aa-itemtip-card {
  font-size: 13px;
}
/* The hover card of a material is placed against the whole row (just beyond the amount), not against the name:
   a name that wraps over two lines would otherwise push the card far away. The whole row is the hover area. */
.aa-rb-row {
  position: relative;
}
.aa-rb-item .aa-itemtip {
  position: static;
}
.aa-rb-row:hover .aa-itemtip-card {
  display: block;
}

/* ===== THEME COLOURS (dark + light) ===== */
/* Colours for the wiki's two themes. Light: wiki set to Day, or Auto with a light browser. Dark: Night, or Auto with a dark browser. */
/* LIGHT */
html.skin-theme-clientpref-day .aa-rb { background: linear-gradient(to bottom, #fffaf0, #f5ecdb); border-color: #c9b998; border-radius: 10px; box-shadow: 0 6px 18px rgba(80, 55, 25, .22); color: #3a2f26; }
html.skin-theme-clientpref-day .aa-rb-coinlabel,
html.skin-theme-clientpref-day .aa-rb-amount { color: #5b4e41; }
html.skin-theme-clientpref-day .aa-rb-kind,
html.skin-theme-clientpref-day .aa-rb-grade,
html.skin-theme-clientpref-day .aa-rb-chiplabel,
html.skin-theme-clientpref-day .aa-rb-label,
html.skin-theme-clientpref-day .aa-rb-note { color: #7a6e5e; }
html.skin-theme-clientpref-day .aa-rb-labor { color: #8a5f00; }
html.skin-theme-clientpref-day .aa-rb-sep { background: linear-gradient(to right, transparent, #c4b391, transparent); }
html.skin-theme-clientpref-day .aa-rb-chip { border-color: #c4b391; background: rgba(58, 47, 38, .07); color: #8a5f00; }
html.skin-theme-clientpref-day .aa-rb-row:hover { background: rgba(58, 47, 38, .07); }
html.skin-theme-clientpref-day .aa-rb span[style*="color"] { filter: brightness(.62) saturate(1.25); }
html.skin-theme-clientpref-day .aa-itemtip > :not(.aa-itemtip-card) [style*="color"],
html.skin-theme-clientpref-day .aa-itemtip > [style*="color"]:not(.aa-itemtip-card) { filter: brightness(.62) saturate(1.25); }
